<?php require_once __DIR__.'/../config/bootstrap.php'; require_client();$pdo=db();$id=(int)$_GET['id'];$st=$pdo->prepare('SELECT e.* FROM encomendas e WHERE e.id=? AND e.cliente_id=?');$st->execute([$id,current_user()['id']]);$eRow=$st->fetch();if(!$eRow)exit('Encomenda não encontrada.');$it=$pdo->prepare('SELECT ei.*,p.nome FROM encomenda_itens ei JOIN produtos p ON p.id=ei.produto_id WHERE ei.encomenda_id=?');$it->execute([$id]);$items=$it->fetchAll();include __DIR__.'/../includes/header.php'; ?><div class="no-print page-head"><h1>Imprimir encomenda</h1><button class="btn primary" onclick="printPage()">Imprimir</button></div><div class="card"><div class="print-header"><h1><?=e(setting('nome_livraria',APP_NAME))?></h1><div><?=e(setting('endereco_livraria'))?> · <?=e(setting('telefone_livraria'))?></div></div><h2>Encomenda <?=e($eRow['numero'])?></h2><p><?=datetime_br($eRow['data_hora'])?></p><div class="table-wrap"><table class="table"><thead><tr><th>Produto</th><th>Qtd.</th><th>Preço</th><th>Subtotal</th></tr></thead><tbody><?php foreach($items as $i): ?><tr><td><?=e($i['nome'])?></td><td><?=e($i['quantidade'])?></td><td><?=money($i['preco_unitario'])?></td><td><?=money($i['subtotal'])?></td></tr><?php endforeach;?></tbody></table></div><div class="total-line total"><span>Total</span><strong><?=money($eRow['total'])?></strong></div><p>Status: <?=e($eRow['status'])?></p><p>Observações: <?=nl2br(e($eRow['observacoes']))?></p></div><?php include __DIR__.'/../includes/footer.php'; ?>
